files.Caddyfile:
{
	auto_https off
	admin off
	frankenphp {
		worker {
			file /app/frankenphp/worker.php
			num 16
			env BLOG_DSN "mysql:host=127.0.0.1;port=53340;dbname=bench;user=root;password=bench;charset=utf8mb4"
			env BLOG_STMT_CACHE "0"
			env BLOG_EMULATE_PREPARES "1"
			env BLOG_UPSTREAM ""
		}
	}
}
http://127.0.0.1:8083 {
	bind 127.0.0.1
	root * /app/frankenphp
	rewrite * /worker.php
	php
}

